class Solution { public List<List<Integer>> findSubsequences(int[] nums){List<List<Integer>> answer=new ArrayList<>();dfs(0,nums,new ArrayList<>(),answer);return answer;}private void dfs(int start,int[] nums,List<Integer> path,List<List<Integer>> answer){if(path.size()>=2)answer.add(new ArrayList<>(path));Set<Integer> used=new HashSet<>();for(int i=start;i<nums.length;i++){if((!path.isEmpty()&&nums[i]<path.get(path.size()-1))||!used.add(nums[i]))continue;path.add(nums[i]);dfs(i+1,nums,path,answer);path.remove(path.size()-1);}} }
